{"tool":"write","path":"tests/test_export.py","content":"import unittest

from reports.export import export_csv


class ExportCsvTests(unittest.TestCase):
    def test_basic_rows_and_columns(self):
        rows = [
            {"name": "Alice", "age": 30},
            {"name": "Bob", "age": 41},
        ]
        self.assertEqual(export_csv(rows, ["name", "age"]), "name,age\r\nAlice,30\r\nBob,41\r\n")

    def test_missing_fields_and_none_become_empty(self):
        rows = [{"a": None, "b": 2}, {"b": 3, "unselected": "ignored"}]
        self.assertEqual(export_csv(rows, ["a", "b"]), "a,b\r\n,2\r\n,3\r\n")

    def test_quoting_embedded_comma_quote_and_newlines(self):
        rows = [
            {
                "text": "line1\r\nline2, \"quoted\"",
                "plain": "x",
            }
        ]
        self.assertEqual(
            export_csv(rows, ["text", "plain"]),
            'text,plain\r\n"line1\r\nline2, ""quoted""",x\r\n',
        )

    def test_generator_rows_and_columns(self):
        rows = ({"a": i, "b": i * 2} for i in range(2))
        columns = (name for name in ["a", "b"])
        self.assertEqual(export_csv(rows, columns), "a,b\r\n0,0\r\n1,2\r\n")

    def test_empty_columns_and_empty_rows(self):
        self.assertEqual(export_csv([], []), "\r\n")
        self.assertEqual(export_csv([{"a": 1}], []), "\r\n\r\n")

    def test_duplicate_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([{"a": 1}], ["a", "a"])

    def test_non_string_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([{"1": 1}], [1])

    def test_unicode_preserved(self):
        self.assertEqual(export_csv([{"a": "café"}], ["a"]), "a\r\ncafé\r\n")


if __name__ == "__main__":
    unittest.main()
